const tableToEdit=(e,t,o)=>{if(!o.element.ds_config)return;o.element.ds_config.list.find(e=>"tableView"===e.name).reqAfter=(e,t)=>{if(t?.data?.views?.grid?.body){let e=t.data.views.grid.body;if(e.gridEditMode={mode:"multipleRow",rowBtns:["update","add"]},"[object String]"===Object.prototype.toString.call(e.columns[0])){let t=e.columns[0];e.columns[0]={name:t}}e.columns[0].rowEditable=!0}return t}};export{tableToEdit};